export const ReadMeEInvoicingDtoSchema = {
    type: 'object',
    properties: {
        directoryLineStatus: {
            nullable: true,
            allOf: [
                {
                    $ref: '#/components/schemas/DirectoryLineStatus'
                }
            ]
        },
        registrationStatus: {
            nullable: true,
            allOf: [
                {
                    $ref: '#/components/schemas/RegistrationStatus'
                }
            ]
        },
        revokedAt: {
            format: 'date-time',
            type: 'string',
            nullable: true,
            description: 'Date de demande de révocation de la ligne d\'annuaire. C\'est ce champ qui distingue un statut "revoked" d\'un statut "inactive" ordinaire côté front.'
        },
        dateFrom: {
            type: 'string',
            nullable: true,
            example: '2026-09-01',
            description: 'Miroir en base de la date d\'effet de la ligne d\'annuaire chez Docoon, au format `YYYY-MM-DD` (Docoon impose J+1 minimum). Date nue et non un timestamp, pour qu\'aucune heure ne réintroduise un décalage de fuseau. **Pas une date d\'origine** : la relance d\'une ligne en erreur la recalcule à J+1 et la repersiste, donc elle avance dans le temps. Pour une date de demande stable, c\'est `directoryLineCreatedAt` — exposé par `GET /v2/e-invoicing/directory-line/status`, mais cet endpoint interroge Docoon en direct (à ne pas appeler au boot) et le champ est absent sur un `PENDING` synthétique. `null` signifie « aucune date d\'effet lisible ici » — soit aucune en base, soit lecture indisponible (cf. la description du bloc `eInvoicing`). Ce n\'est pas un indicateur de progression, et selon l\'état de l\'inscription le champ peut se remplir seul, ne se remplir qu\'après une action admin, ou ne jamais se remplir. Pour l\'avancement, lire `directoryLineStatus` ici et `GET /v2/e-invoicing/registration` pour l\'état de la saga — ne pas construire d\'état d\'attente sur ce `null`.'
        },
        mandatStatus: {
            nullable: true,
            description: 'The status of the PDP mandate',
            allOf: [
                {
                    $ref: '#/components/schemas/PDPMandateStatus'
                }
            ]
        },
        addressingIdentifier: {
            type: 'string',
            nullable: true,
            description: 'Identifiant d\'adressage dans l\'annuaire, à communiquer à ses fournisseurs pour recevoir leurs factures électroniques. Renvoyé même quand la ligne est révoquée : l\'affichage est une décision front. `null` si aucune valeur n\'est persistée.'
        },
        isLegacyMandate: {
            type: 'boolean',
            description: 'True quand le mandat PDP courant est un mandat legacy (version 1, antérieur à la vérification d\'identité) — le grandfathering d\'affichage v1 (D-9396) branche dessus. Fail-safe : false quand le mandat est absent ou la lecture indisponible. Dérivé de la version du mandat uniquement, jamais de identityVerificationRequired (qui couvre aussi les bypass admin v2).'
        },
        platformTransfer: {
            nullable: true,
            description: 'Transfert de portabilité sortant en cours (le client rejoint Abby). Non-null uniquement si la ligne d\'annuaire est `SUSPENDED`, le dossier PA Hub est `OUTBOUND` et un `request_id` est persisté. `null` dans tous les autres cas (pas de dossier, dossier entrant, ligne non suspendue, lecture indisponible) — jamais une erreur HTTP.',
            allOf: [
                {
                    $ref: '#/components/schemas/ReadMePlatformTransferDto'
                }
            ]
        }
    },
    required: [
        'directoryLineStatus',
        'registrationStatus',
        'revokedAt',
        'dateFrom',
        'mandatStatus',
        'addressingIdentifier',
        'isLegacyMandate',
        'platformTransfer'
    ]
} as const;

